create type public.app_role as enum ('admin','member');
create type public.member_status as enum ('pending','approved','removed');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text unique not null, full_name text, avatar_url text, role public.app_role not null default 'member', status public.member_status not null default 'pending', created_at timestamptz not null default now());
create table public.groups (id uuid primary key default gen_random_uuid(), name text not null check(char_length(name) between 1 and 100), created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.group_members (group_id uuid references public.groups(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, joined_at timestamptz not null default now(), primary key(group_id,user_id));
create table public.expenses (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, description text not null, amount numeric(12,2) not null check(amount>0), currency text not null default 'INR', paid_by uuid not null references public.profiles(id), created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.expense_splits (expense_id uuid references public.expenses(id) on delete cascade, user_id uuid references public.profiles(id), amount numeric(12,2) not null check(amount>=0), primary key(expense_id,user_id));
create table public.settlements (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, paid_by uuid not null references public.profiles(id), paid_to uuid not null references public.profiles(id), amount numeric(12,2) not null check(amount>0), created_at timestamptz not null default now(), check(paid_by<>paid_to));
alter table public.profiles enable row level security; alter table public.groups enable row level security; alter table public.group_members enable row level security; alter table public.expenses enable row level security; alter table public.expense_splits enable row level security; alter table public.settlements enable row level security;
create function public.approved() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and status='approved') $$;
create function public.in_group(g uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from group_members where group_id=g and user_id=auth.uid()) $$;
create policy "own profile" on public.profiles for select using (id=auth.uid());
create policy "group members see profiles" on public.profiles for select using (exists(select 1 from group_members gm join group_members mine on mine.group_id=gm.group_id where gm.user_id=profiles.id and mine.user_id=auth.uid()));
create policy "members see groups" on public.groups for select using (in_group(id)); create policy "approved create groups" on public.groups for insert with check (approved() and created_by=auth.uid());
create policy "members see membership" on public.group_members for select using (in_group(group_id)); create policy "creator joins group" on public.group_members for insert with check (user_id=auth.uid() and exists(select 1 from groups where id=group_id and created_by=auth.uid()));
create policy "group expense read" on public.expenses for select using(in_group(group_id)); create policy "group expense add" on public.expenses for insert with check(approved() and in_group(group_id) and paid_by=auth.uid() and created_by=auth.uid());
create policy "split read" on public.expense_splits for select using(exists(select 1 from expenses where id=expense_id and in_group(group_id))); create policy "split add" on public.expense_splits for insert with check(exists(select 1 from expenses where id=expense_id and created_by=auth.uid()));
create policy "settlement read" on public.settlements for select using(in_group(group_id)); create policy "settlement add" on public.settlements for insert with check(approved() and in_group(group_id) and paid_by=auth.uid());
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name,avatar_url) values(new.id,lower(new.email),coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),new.raw_user_meta_data->>'avatar_url'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
